/**
 * Einziger Ort, der die Tabelle free_leads kennt.
 *
 * Kernregel (Spec §7 "Wiedereintritt"): Erneutes Eintragen legt NIE eine zweite
 * Zeile an, sondern schickt den Link neu. Ein harter Unique-Index ohne diese
 * Logik sperrt jeden aus, der die Mail nie anklickt — der Funnel frisst still Leads.
 *
 * Nebenlaeufigkeit: Jeder Lese-dann-Schreib-Pfad kann sich mit einer parallelen
 * Anfrage ueberschneiden (Doppelklick, Client-Retry, verteilter Angreifer). Kein
 * Pfad darf deshalb in einer unbehandelten D1-Exception enden — ein Fremder, der
 * seinen Bestaetigungslink anklickt, bekommt nie eine 500.
 */

import { TOKEN_TTL_HOURS, RESEND_MAX_PER_HOUR, PENDING_TTL_DAYS, INACTIVE_TTL_DAYS, BUILDING_TIMEOUT_MINUTES } from './constants.js';

const HOUR_MS = 60 * 60 * 1000;

function iso(date) {
  return date.toISOString().replace('T', ' ').slice(0, 19);
}

function newToken() {
  const bytes = crypto.getRandomValues(new Uint8Array(32));
  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
}

function plusHours(date, hours) {
  return new Date(date.getTime() + hours * HOUR_MS);
}

/**
 * Erkennt eine verletzte UNIQUE-Bedingung. D1 verpackt den SQLite-Fehler, der
 * Index-Name steckt im Text ("UNIQUE constraint failed: free_leads.email_norm").
 */
function isUniqueViolation(err, column) {
  const msg = `${err?.message ?? ''} ${err?.cause?.message ?? ''}`;
  if (!/UNIQUE constraint failed/i.test(msg)) return false;
  return column ? msg.includes(column) : true;
}

async function byEmailNorm(db, emailNorm) {
  return db.prepare('SELECT * FROM free_leads WHERE email_norm = ?').bind(emailNorm).first();
}

async function byId(db, id) {
  return db.prepare('SELECT * FROM free_leads WHERE id = ?').bind(id).first();
}

/** true, wenn der Handle bereits von einem ANDEREN, bestaetigten Lead belegt ist. */
async function handleTakenByOther(db, handleNorm, emailNorm) {
  if (!handleNorm) return false;
  const row = await db
    .prepare(
      `SELECT id FROM free_leads
       WHERE handle_norm = ? AND email_norm != ? AND confirmed_at IS NOT NULL`
    )
    .bind(handleNorm, emailNorm)
    .first();
  return !!row;
}

function isTokenExpired(lead, now) {
  return new Date(lead.token_expires.replace(' ', 'T') + 'Z').getTime() <= now.getTime();
}

/**
 * Legt eine neue Zeile an.
 * @returns Ergebnis-Objekt, oder null wenn eine parallele Anfrage schneller war.
 */
async function insertNew(db, clean, ip, now) {
  const token = newToken();
  try {
    await db
      .prepare(
        `INSERT INTO free_leads
           (name, email, email_norm, handle, handle_norm, branche, ziel, stimmung,
            farbe, stand, taetigkeit, consent, testimonial_consent, source, token, token_expires, resend_count, last_sent_at,
            ip, status, created_at, sprache)
         VALUES (?,?,?,?,?,?,?,?,?,?,?,1,?,?,?,?,1,?,?, 'pending', ?, ?)`
      )
      .bind(
        clean.name, clean.email, clean.emailNorm, clean.handle, clean.handleNorm,
        clean.branche, clean.ziel, clean.stimmung, clean.farbe, clean.stand, clean.taetigkeit || '',
        clean.testimonialConsent ? 1 : 0, clean.source,
        token, iso(plusHours(now, TOKEN_TTL_HOURS)), iso(now), ip, iso(now), clean.sprache === 'en' ? 'en' : 'de'
      )
      .run();
  } catch (err) {
    // Rennen verloren: zwischen Lookup und INSERT hat eine parallele Anfrage
    // dieselbe Adresse angelegt. Kein Fehlerfall — der Verlierer tritt einfach
    // wieder ein und bekommt seinen Link.
    if (isUniqueViolation(err, 'email_norm')) {
      console.error('[leads] INSERT-Rennen um email_norm verloren, Wiedereintritt folgt:', err.message);
      return null;
    }
    console.error('[leads] INSERT fehlgeschlagen:', err);
    throw err;
  }

  const lead = await byEmailNorm(db, clean.emailNorm);
  return { lead, action: 'created', mail: 'confirm' };
}

/**
 * Wiedereintritt auf einer bestehenden Zeile.
 *
 * Der Resend-Deckel steckt im WHERE des UPDATEs: Pruefung UND Hochzaehlen sind
 * EIN Statement. Getrennt (erst lesen, dann pruefen, dann schreiben) laufen N
 * parallele Anfragen alle gegen denselben veralteten Zaehler, passieren alle den
 * Check und loesen N Mails aus — ein umgehbarer Deckel ist kein Deckel, und der
 * Deckel ist die einzige Verteidigung eines fremden Postfachs gegen Mailbombing.
 */
async function reenter(db, clean, ip, now, existing) {
  // Fertig -> Ergebnis-Link, nicht neu bauen.
  if (existing.status === 'ready') {
    return { lead: existing, action: 'ready', mail: 'result' };
  }

  // Laeuft gerade -> Link zur Build-Seite.
  if (existing.status === 'confirmed' || existing.status === 'building') {
    return { lead: existing, action: 'building', mail: 'result' };
  }

  const retry = existing.status === 'failed';
  const expired = isTokenExpired(existing, now);
  const keepToken = !retry && !expired;

  const token = keepToken ? existing.token : newToken();
  const expires = keepToken ? existing.token_expires : iso(plusHours(now, TOKEN_TTL_HOURS));
  // Fixe Breite ISO 'YYYY-MM-DD HH:MM:SS' -> Textvergleich == Zeitvergleich.
  const windowStart = iso(new Date(now.getTime() - HOUR_MS));

  const res = await db
    .prepare(
      `UPDATE free_leads SET
         name=?, email=?, handle=?, handle_norm=?, branche=?, ziel=?, stimmung=?,
         farbe=?, stand=?, taetigkeit=?, testimonial_consent=?, source=?, sprache=?, token=?, token_expires=?, token_used_at=NULL,
         resend_count = CASE WHEN last_sent_at IS NULL OR last_sent_at <= ?
                             THEN 1 ELSE resend_count + 1 END,
         last_sent_at=?, ip=?, status='pending', fail_reason=''
       WHERE id=?
         AND (last_sent_at IS NULL OR last_sent_at <= ? OR resend_count < ?)`
    )
    .bind(
      clean.name, clean.email, clean.handle, clean.handleNorm, clean.branche,
      clean.ziel, clean.stimmung, clean.farbe, clean.stand, clean.taetigkeit || '', clean.testimonialConsent ? 1 : 0,
      clean.source, clean.sprache === 'en' ? 'en' : 'de', token, expires,
      windowStart, iso(now), ip, existing.id, windowStart, RESEND_MAX_PER_HOUR
    )
    .run();

  // Keine Zeile getroffen == Quote im laufenden Fenster ausgeschoepft.
  if ((res.meta?.changes ?? 0) === 0) {
    return { lead: existing, action: 'throttled', mail: 'none' };
  }

  const lead = await byId(db, existing.id);
  const action = retry ? 'retry' : expired ? 'renewed' : 'resent';
  return { lead, action, mail: 'confirm' };
}

/**
 * Legt an oder tritt wieder ein.
 * @returns {{lead: object, action: string, mail: 'confirm'|'result'|'none'}}
 */
export async function upsertLead(db, clean, ip, now = new Date()) {
  const existing = await byEmailNorm(db, clean.emailNorm);

  if (await handleTakenByOther(db, clean.handleNorm, clean.emailNorm)) {
    return { lead: existing ?? null, action: 'handle_taken', mail: 'none' };
  }

  if (existing) return reenter(db, clean, ip, now, existing);

  const created = await insertNew(db, clean, ip, now);
  if (created) return created;

  const raced = await byEmailNorm(db, clean.emailNorm);
  if (!raced) {
    // UNIQUE auf email_norm verletzt, aber die Zeile ist nicht auffindbar —
    // dafuer gibt es keine sinnvolle Erklaerung. Lieber laut als still falsch.
    console.error('[leads] UNIQUE-Verletzung ohne auffindbare Zeile:', clean.emailNorm);
    throw new Error('leads: UNIQUE-Verletzung auf email_norm ohne auffindbare Zeile');
  }
  return reenter(db, clean, ip, now, raced);
}

export async function findByToken(db, token) {
  if (!token) return null;
  return db.prepare('SELECT * FROM free_leads WHERE token = ?').bind(token).first();
}

/**
 * Entwertet den Token und setzt den Lead auf confirmed. Genau einmal moeglich.
 * @returns {{ok: boolean, lead?: object, reason?: 'not_found'|'expired'|'used'|'handle_taken'}}
 */
export async function confirmLead(db, token, now = new Date()) {
  const lead = await findByToken(db, token);
  if (!lead) return { ok: false, reason: 'not_found' };
  if (lead.token_used_at) return { ok: false, reason: 'used' };
  if (isTokenExpired(lead, now)) return { ok: false, reason: 'expired' };

  try {
    await db
      .prepare(
        `UPDATE free_leads
           SET token_used_at=?, confirmed_at=?, status='confirmed'
         WHERE id=? AND token_used_at IS NULL`
      )
      .bind(iso(now), iso(now), lead.id)
      .run();
  } catch (err) {
    // Zwei PENDING-Leads duerfen denselben Handle tragen (kein Griefing-Lock).
    // Bestaetigen beide, greift beim Zweiten der partielle Handle-Index. Das ist
    // ein regulaerer Ausgang, kein Serverfehler: der Klick auf einen echten
    // Bestaetigungslink darf nie in einer 500 enden.
    if (isUniqueViolation(err, 'handle_norm')) {
      console.error('[leads] confirmLead: Handle inzwischen fremd bestaetigt:', lead.handle_norm);
      return { ok: false, reason: 'handle_taken' };
    }
    console.error('[leads] confirmLead fehlgeschlagen:', err);
    throw err;
  }

  return { ok: true, lead: await byId(db, lead.id) };
}

/**
 * DSGVO: unbestaetigte Leads nach PENDING_TTL_DAYS loeschen — MITSAMT ihrer
 * R2-Ablage (hochgeladenes Foto `avatar.bin`, ggf. Frames). Ohne den R2-Teil
 * waere die Loeschung eine halbe: die Zeile verschwindet, ihr Bild bleibt
 * liegen (Security-Review 07.08., HIGH). `images` ist optional, damit alte
 * Aufrufer nicht brechen; ohne Binding wird nur die DB bereinigt.
 */
export async function cleanupExpired(db, now = new Date(), images = null) {
  const cutoff = iso(new Date(now.getTime() - PENDING_TTL_DAYS * 24 * HOUR_MS));
  // Tokens VOR dem DELETE einsammeln — danach kennt sie niemand mehr.
  let tokens = [];
  try {
    const alte = await db
      .prepare(
        `SELECT token FROM free_leads
          WHERE status = 'pending' AND confirmed_at IS NULL AND created_at < ?`
      )
      .bind(cutoff)
      .all();
    tokens = (alte.results ?? []).map((r) => r.token).filter(Boolean);
  } catch (err) {
    console.error('[leads] Token-Sammlung fuers Aufraeumen fehlgeschlagen:', err);
  }
  const res = await db
    .prepare(
      `DELETE FROM free_leads
        WHERE status = 'pending' AND confirmed_at IS NULL AND created_at < ?`
    )
    .bind(cutoff)
    .run();
  // R2 non-fatal: ein R2-Ruckler darf die DB-Loeschung nicht kippen. Ein
  // uebrig gebliebenes Objekt faengt der naechste Lauf NICHT mehr (Token weg) —
  // deshalb loggen, damit es wenigstens auffindbar ist.
  if (images && tokens.length) {
    for (const t of tokens) {
      await loescheLeadAblage(images, t);
    }
  }
  return res.meta?.changes ?? 0;
}

// Automatische Karte aus generate.js, an der niemand gearbeitet hat: gehört zum Lead
// und geht mit ihm. Jede andere Karte heißt Zusammenarbeit, der Lead bleibt.
const LEERE_AUTO_KARTE = `coalesce(c.status, '') = 'briefing'
   AND coalesce(c.notes, '') LIKE 'Automatisch aus Free-Content-Funnel%'
   AND NOT EXISTS (SELECT 1 FROM tickets x WHERE x.client_id = c.id)
   AND NOT EXISTS (SELECT 1 FROM nachrichten x WHERE x.client_id = c.id)
   AND NOT EXISTS (SELECT 1 FROM payments x WHERE x.client_id = c.id)
   AND NOT EXISTS (SELECT 1 FROM beitraege x WHERE x.client_id = c.id)
   AND NOT EXISTS (SELECT 1 FROM reel_auftrag x WHERE x.client_id = c.id)`;

// Letzter Kontakt = jüngster Zeitpunkt aus Anlage, Bestätigung, Bau, letzter Mail
// und ihrem letzten Klick (funnel_events). max() mit NULL ergibt NULL — daher coalesce.
// Abgleich über f.email: email_norm schneidet +Tags ab, Karte und Spiegel tragen die rohe Adresse.
const INAKTIV_WHERE = `f.confirmed_at IS NOT NULL
   AND max(f.created_at, coalesce(f.confirmed_at, ''), coalesce(f.generated_at, ''), coalesce(f.last_sent_at, ''),
           coalesce((SELECT max(e.created_at) FROM funnel_events e WHERE e.token = f.token), '')) < ?
   AND NOT EXISTS (SELECT 1 FROM clients c
                    WHERE (c.contact = f.email OR lower(trim(c.email)) IN (f.email_norm, lower(trim(f.email))))
                      AND NOT (${LEERE_AUTO_KARTE}))
   AND NOT EXISTS (SELECT 1 FROM submissions s JOIN clients c ON c.id = s.client_id
                    WHERE s.type = 'free_content' AND s.email = f.email AND NOT (${LEERE_AUTO_KARTE}))`;

/**
 * DSGVO (DSE Nr. 08, #400): bestätigte Vorschauen ohne Zusammenarbeit
 * INACTIVE_TTL_DAYS nach dem letzten Kontakt löschen, und zwar überall, wo der
 * Funnel sie abgelegt hat: R2, CRM-Spiegel in submissions, leere Auto-Karte samt
 * Verlauf und Wiedervorlage. Zeilen in funnel_events behalten nur den Token
 * (ohne Lead kein Personenbezug), die Zählung bleibt.
 */
export async function cleanupInactive(db, now = new Date(), images = null) {
  const cutoff = iso(new Date(now.getTime() - INACTIVE_TTL_DAYS * 24 * HOUR_MS));
  const alte = await db
    .prepare(`SELECT f.id, f.token, f.email FROM free_leads f WHERE ${INAKTIV_WHERE}`)
    .bind(cutoff)
    .all();
  let geloescht = 0;
  for (const z of alte.results ?? []) {
    // Erst R2, dann die Zeilen: bricht R2 ab, findet der nächste Lauf den Token noch.
    if (images && z.token && !(await loescheLeadAblage(images, z.token))) continue;
    const karten = await db
      .prepare(`SELECT c.id FROM clients c WHERE c.contact = ? AND ${LEERE_AUTO_KARTE}`)
      .bind(z.email)
      .all();
    const kartenZeilen = (karten.results ?? []).flatMap((k) => [
      db.prepare('DELETE FROM activity WHERE client_id = ?').bind(k.id),
      db.prepare('DELETE FROM events WHERE client_id = ?').bind(k.id),
      db.prepare('DELETE FROM submissions WHERE client_id = ?').bind(k.id),
      db.prepare('DELETE FROM clients WHERE id = ?').bind(k.id),
    ]);
    // batch: alles oder nichts, sonst bliebe bei einem Abbruch eine halbe Löschung ohne Lead.
    await db.batch([
      ...kartenZeilen,
      db.prepare("DELETE FROM submissions WHERE type = 'free_content' AND email = ?").bind(z.email),
      db.prepare('DELETE FROM free_leads WHERE id = ?').bind(z.id),
    ]);
    geloescht++;
  }
  return geloescht;
}

/** Loescht alle R2-Objekte eines Leads (Foto + Frames + Captions). WIRFT NIE. */
export async function loescheLeadAblage(images, token) {
  try {
    const liste = await images.list({ prefix: `free/${token}/`, limit: 40 });
    await Promise.all((liste.objects ?? []).map((o) => images.delete(o.key)));
    return true;
  } catch (err) {
    console.error(`[leads] R2-Aufraeumen fuer free/${token}/ fehlgeschlagen:`, err);
    return false;
  }
}

/**
 * Eskalations-Knopf (Missbrauchs-Meldung aus dem Reveal): sperrt den Feed.
 * Der Token geht nur an die Mail-Inhaberin — wer melden kann, ist also immer
 * die Betroffene selbst. Claim atomar ueber reported_at IS NULL (idempotent);
 * status='failed' + fail_reason='gemeldet' nimmt Build-Screen/Reveal die
 * Datengrundlage, die R2-Loeschung uebernimmt der Aufrufer (index.js).
 * @returns {Promise<{ok: boolean, lead?: object}>} wirft nie
 */
export async function reportLead(db, token, now = new Date()) {
  if (!token) return { ok: false };
  try {
    const claim = await db
      .prepare(
        `UPDATE free_leads
            SET reported_at=?, status='failed', fail_reason='gemeldet'
          WHERE token=? AND reported_at IS NULL`
      )
      .bind(iso(now), token)
      .run();
    if ((claim.meta?.changes ?? 0) === 0) return { ok: false };
    const lead = await findByToken(db, token);
    return { ok: true, lead };
  } catch (err) {
    console.error('[leads] Meldung konnte nicht gespeichert werden:', err);
    return { ok: false };
  }
}

/**
 * Spec §9 Sackgasse: ein hart gekillter Worker (CPU-Limit/OOM) zwischen dem
 * atomaren Claim in generate.js (setzt status='building' + generated_at) und
 * markiereFehler laesst eine Zeile fuer immer bei 'building' haengen — nie
 * retried, kein Founder-Alarm. reenter() (oben) behandelt 'building' als "laeuft
 * noch" und schickt sie nur auf den Build-Screen zurueck: ohne diesen Sweep gibt
 * es aus dieser Zeile keinen Ausweg.
 *
 * generated_at ist der verlaessliche Claim-Zeitstempel: der Claim setzt ihn
 * atomar zu Beginn, und NUR markiereFehler loescht ihn wieder — eine Zeile, die
 * noch 'building' ist, traegt also immer den echten Zeitpunkt des Claims. Aelter
 * als BUILDING_TIMEOUT_MINUTES: mit an Sicherheit grenzender Wahrscheinlichkeit
 * tot. Kippt auf 'failed' und loescht generated_at (derselbe Riegel-Freigabe-
 * Mechanismus wie markiereFehler), damit reenter() sie als retrybar sieht.
 *
 * KEIN Alarm pro Zeile hier: ein Burst gekillter Worker wuerde die Founder sonst
 * zuspammen. 'failed' ist bereits der ehrliche Zustand, der die Sackgasse
 * beendet — der naechste Wiedereintritt macht daraus regulaer einen neuen
 * Versuch.
 *
 * @returns {Promise<number>} Anzahl gekippter Zeilen
 */
export async function sweepStaleBuilding(db, now = new Date()) {
  const cutoff = iso(new Date(now.getTime() - BUILDING_TIMEOUT_MINUTES * 60 * 1000));
  const res = await db
    .prepare(
      `UPDATE free_leads SET status='failed', generated_at=NULL, build_step='', fail_reason=''
        WHERE status='building' AND generated_at < ?`
    )
    .bind(cutoff)
    .run();
  const anzahl = res.meta?.changes ?? 0;
  if (anzahl > 0) {
    console.error(`[leads] ${anzahl} haengengebliebene(n) Build(s) (>${BUILDING_TIMEOUT_MINUTES}min) auf 'failed' gesetzt`);
  }
  return anzahl;
}
